export class Ed25519{static PUBLIC_KEY="MCowBQYDK2VwAyEAALc1CMplaumQq5TK0JI7LpupBVkO5RH9mE0Zz8MSEWc=";static b64ToBytes(t){const e=atob(String(t).replace(/\s+/g,"")),r=new Uint8Array(e.length);for(let t=0;t<e.length;t++)r[t]=e.charCodeAt(t);return r}static async importKey(t=Ed25519.PUBLIC_KEY){return crypto.subtle.importKey("spki",Ed25519.b64ToBytes(t),{name:"Ed25519"},!1,["verify"])}static canonical(t){return JSON.stringify(t,Object.keys(t).sort())}static async verify(t,e,r=Ed25519.PUBLIC_KEY){try{const c=await Ed25519.importKey(r),n=(new TextEncoder).encode(Ed25519.canonical(t));return await crypto.subtle.verify({name:"Ed25519"},c,Ed25519.b64ToBytes(e),n)}catch{return!1}}static supported(){return"undefined"!=typeof crypto&&!!crypto.subtle}}